                    { var __cv = (System.IComparable)_outputPrintMonochromeThreshold; if (__cv.CompareTo(0) < 0 || __cv.CompareTo(255) > 0) yield return "Monochrome threshold must be between 0 and 255."; }
                    break;
                case nameof(AutoCropDifference):
                    { var __cv = (System.IComparable)_autoCropDifference; if (__cv.CompareTo(0) < 0 || __cv.CompareTo(255) > 0) yield return "AutoCropDifference must be between 0 and 255."; }
