                    break;
                case nameof(WebRequestTimeout):
                    { var __cv = (System.IComparable)_webRequestTimeout; if (__cv.CompareTo(1) < 0 || __cv.CompareTo(100) > 0) yield return "WebRequestTimeout must be between 1 and 100 seconds."; }
